import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Home from './components/Home';
import About from './components/About';
import Events from './components/Events';
import Login from './components/Login';
import Register from './components/Register';
import Dashboard from './components/Dashboard';

function App(){
  const [route, setRoute] = useState('home');
  const [token, setToken] = useState(localStorage.getItem('token'));
  const [user, setUser] = useState(null);

  useEffect(()=>{
    if (token){
      fetch(`${process.env.REACT_APP_API || 'http://localhost:4000'}/api/dashboard/me`,{
        headers:{Authorization:`Bearer ${token}`}
      }).then(r=>r.json()).then(d=>{ if (d.user) setUser(d.user); });
    }
  },[token]);

  function onLogin(tkn, u){
    localStorage.setItem('token', tkn); setToken(tkn); setUser(u); setRoute('dashboard');
  }
  function onLogout(){ localStorage.removeItem('token'); setToken(null); setUser(null); setRoute('home'); }

  return (
    <div>
      <Navbar onNavigate={setRoute} onLogout={onLogout} user={user} />
      <div className="container">
        {route==='home' && <Home />}
        {route==='about' && <About />}
        {route==='events' && <Events />}
        {route==='login' && <Login onLogin={onLogin} onNavigate={setRoute} />}
        {route==='register' && <Register onNavigate={setRoute} />}
        {route==='dashboard' && <Dashboard user={user} token={token} />}
      </div>
    </div>
  );
}

export default App;
